"""Italiano — livello principiante (200 domande)."""

T = {
"prophets_251": ("Come si chiama il Profeta dell'Islam?", ["Muhammad ﷺ", "Ibrahim", "Musa", "'Isa"], "Il Profeta dell'Islam è Muhammad ﷺ, figlio di 'Abdullah."),
"prophets_252": ("Isma'il e Ishaq sono i figli di quale profeta?", ["Ibrahim", "Musa", "Nuh", "Dawud"], "«Lode ad Allah che, nonostante la vecchiaia, mi ha donato Isma'il e Ishaq» (14:39)."),
"prophets_253": ("Quale profeta Allah ha elevato a Sé?", ["'Isa", "Yunus", "Ayyub", "Idris"], "«Allah lo ha elevato a Sé» (4:158)."),
"prophets_254": ("Chi è la madre del profeta 'Isa?", ["Maryam", "Asiya", "Hajar", "Sara"], "Maryam, alla quale è dedicata un'intera sura del Corano."),
"prophets_255": ("Chi è il primo essere umano creato da Allah?", ["Adam", "Nuh", "Ibrahim", "Idris"], "Adam è il primo uomo, al quale Allah insegnò tutti i nomi."),
"prophets_256": ("Per quale profeta il fuoco divenne frescura e pace?", ["Ibrahim", "Musa", "Yusuf", "Sulayman"], "«O fuoco, sii frescura e pace per Ibrahim.»"),
"prophets_257": ("Quale profeta portava un bastone che divenne un serpente?", ["Musa", "Harun", "Yahya", "Zakariyya"], "Allah chiese a Musa: «Che cos'è quello nella tua mano destra?»"),
"prophets_258": ("Quale profeta vide in sogno undici stelle prostrarsi?", ["Yusuf", "Ya'qub", "Ishaq", "Dawud"], "«O padre mio, ho visto undici stelle, il sole e la luna.»"),
"prophets_259": ("Quale uccello portò una notizia al profeta Sulayman?", ["L'upupa", "Il corvo", "Il falco", "La colomba"], "L'upupa disse: «Ti porto da Saba' una notizia certa» (27:22)."),
"prophets_260": ("Quale profeta è il modello della pazienza nella prova?", ["Ayyub", "Yunus", "Lut", "Shu'ayb"], "Ayyub invocò il suo Signore e fu trovato paziente."),
"prophets_261": ("Da che cosa Allah creò Adam?", ["Dalla polvere", "Dalla luce", "Dal fuoco", "Dal vento"], "«Lo creò dalla polvere, poi gli disse: Sii!» (3:59)."),
"prophets_262": ("A quale profeta Allah parlò direttamente?", ["Musa", "Yusuf", "Yunus", "Salih"], "«E Allah parlò a Musa direttamente.»"),
"prophets_263": ("Quanti profeti vengono dopo Muhammad ﷺ?", ["Nessuno: è l'ultimo dei profeti", "Uno", "Tre", "Sette"], "Muhammad ﷺ è il sigillo dei profeti: nessun profeta viene dopo di lui."),
"prophets_264": ("Quale profeta è chiamato «l'amico intimo» (khalil) di Allah?", ["Ibrahim", "Musa", "'Isa", "Nuh"], "Ibrahim è il padre dei profeti e l'amico intimo del Misericordioso."),
"prophets_265": ("Quale profeta guariva il cieco dalla nascita con il permesso di Allah?", ["'Isa", "Yahya", "Zakariyya", "Ilyas"], "«E guarivi il cieco dalla nascita e il lebbroso con il Mio permesso.»"),
"prophets_266": ("Per quale profeta le montagne ripetevano le lodi di Allah?", ["Dawud", "Sulayman", "Ayyub", "Yunus"], "«O montagne, ripetete con lui le lodi di Allah.»"),
"prophets_267": ("Quale profeta spiegò il sogno del re d'Egitto?", ["Yusuf", "Harun", "Ilyas", "Shu'ayb"], "Yusuf spiegò il sogno delle sette vacche grasse e delle sette magre (12:46-49)."),
"prophets_268": ("Chi è il padre del profeta Yusuf?", ["Ya'qub", "Ishaq", "Ibrahim", "Lut"], "Yusuf è il figlio di Ya'qub, a sua volta figlio di Ishaq."),
"prophets_269": ("Che cosa si aprì davanti a Musa e al suo popolo?", ["Il mare, aperto per salvarli dal Faraone", "Un fiume d'Egitto", "Un lago di Madyan", "Un pozzo del deserto"], "«E quando aprimmo il mare per voi e vi salvammo.»"),
"prophets_270": ("Che cosa si dice dopo aver pronunciato il nome del Profeta ﷺ?", ["«Che la benedizione e la pace di Allah siano su di lui»", "Niente di particolare", "«Grazie»", "«Arrivederci»"], "Si invocano su di lui la benedizione e la pace: salla-Llahu 'alayhi wa sallam."),
"prophets_271": ("Quale profeta chiamò il suo popolo per moltissimo tempo prima del diluvio?", ["Nuh", "Hud", "Salih", "Shu'ayb"], "«Inviammo Nuh al suo popolo: ammonisci il tuo popolo.»"),
"prophets_272": ("Sulayman è il figlio di quale profeta?", ["Dawud", "Ya'qub", "Ishaq", "Yunus"], "«E a Dawud donammo Sulayman: che eccellente servo!» (38:30)."),
"prophets_273": ("Quale profeta sconfisse Jalut (Golia)?", ["Dawud", "Sulayman", "Yusha'", "Ilyas"], "«E Dawud uccise Jalut» (2:251)."),
"prophets_274": ("In quanti profeti deve credere un musulmano?", ["In tutti, senza fare distinzioni", "Solo nell'ultimo", "Solo in tre", "Solo in quelli nominati nel Corano"], "Il musulmano crede in tutti i profeti di Allah, senza fare differenze tra loro."),
"prophets_275": ("Chi ha scelto Allah, secondo il Corano?", ["Adam, Nuh, la famiglia di Ibrahim e la famiglia di 'Imran", "I re d'Egitto", "Le tribù di Medina", "Il popolo di Saba'"], "«Allah ha scelto Adam, Nuh, la famiglia di Ibrahim e la famiglia di 'Imran.»"),
"prophets_276": ("In quale paese il profeta Yusuf divenne uomo di fiducia del re?", ["L'Egitto", "Lo Sham", "Lo Yemen", "L'Iraq"], "Yusuf si stabilì in Egitto dopo aver interpretato il sogno del re."),
"prophets_277": ("Quale profeta fu portato di notte alla Moschea al-Aqsa?", ["Muhammad ﷺ", "Musa", "'Isa", "Ibrahim"], "«Gloria a Colui che fece viaggiare di notte il Suo servo.»"),
"prophets_278": ("Quale libro fu dato al profeta Musa?", ["La Torah", "Il Vangelo", "I Salmi", "I Fogli di Ibrahim"], "Allah diede a Musa il Libro e, dopo di lui, fece seguire altri messaggeri."),
"prophets_279": ("Quale libro fu dato al profeta 'Isa?", ["Il Vangelo", "La Torah", "I Salmi", "Il Corano"], "«E gli demmo il Vangelo, in cui vi erano guida e luce.»"),
"prophets_280": ("Quale libro fu dato al profeta Dawud?", ["I Salmi (Zabur)", "La Torah", "Il Vangelo", "I Fogli di Musa"], "«E a Dawud demmo lo Zabur.»"),
"prophets_281": ("Il figlio di quale profeta accettò di essere sacrificato per obbedienza ad Allah?", ["Il figlio di Ibrahim", "Il figlio di Nuh", "Il fratello di Musa", "Il figlio di Ya'qub"], "«O padre mio, fa' ciò che ti è stato ordinato: mi troverai paziente.»"),
"prophets_282": ("Dove mise la madre di Musa il suo bambino per salvarlo?", ["Nel fiume", "In una grotta", "Da una vicina", "Nel deserto"], "«Gettalo nel fiume: Noi te lo restituiremo.»"),
"prophets_283": ("Che cosa disse Yunus nelle tenebre, parole che ogni musulmano ripete?", ["«Non c'è dio all'infuori di Te, gloria a Te, sono stato ingiusto»", "«Dammi la ricchezza»", "«Fammi re»", "«Rendimi forte»"], "L'invocazione di Yunus nel ventre del pesce."),
"prophets_284": ("Chi è il padre del Profeta Muhammad ﷺ?", ["'Abdullah", "Abu Talib", "Al-'Abbas", "Hamza"], "Egli è Muhammad ﷺ, figlio di 'Abdullah, figlio di 'Abd al-Muttalib."),
"prophets_285": ("Chi è la madre del Profeta Muhammad ﷺ?", ["Amina", "Khadija", "'Aisha", "Fatima"], "Amina bint Wahb è la madre del Profeta ﷺ."),
"prophets_286": ("Che cosa disse 'Isa quando era ancora nella culla?", ["«Io sono il servo di Allah»", "«Io sono un re»", "«Io sono un angelo»", "Non disse nulla"], "«In verità io sono il servo di Allah: Egli mi ha dato la Scrittura.»"),
"prophets_287": ("Quale profeta fu inviato al popolo di 'Ad?", ["Hud", "Salih", "Lut", "Shu'ayb"], "«E agli 'Ad, il loro fratello Hud.»"),
"prophets_288": ("Quale profeta fu inviato ai Thamud, con la cammella?", ["Salih", "Hud", "Yunus", "Idris"], "«E ai Thamud, il loro fratello Salih: questa è la cammella di Allah.»"),
"prophets_289": ("Quale profeta è il fratello di Musa, inviato insieme a lui?", ["Harun", "Yusuf", "Yahya", "Ilyas"], "«E dammi un aiutante dalla mia famiglia: Harun, mio fratello.»"),
"prophets_290": ("Quale titolo dà il Corano a Muhammad ﷺ riguardo ai profeti?", ["Il sigillo dei profeti", "Il primo dei profeti", "Il re dei profeti", "Lo scriba dei profeti"], "«Muhammad è il Messaggero di Allah e il sigillo dei profeti.»"),
"prophets_291": ("Che cosa dicono gli angeli a Maryam nel Corano?", ["Che Allah l'ha scelta e purificata", "Che sarà regina", "Che viaggerà", "Che insegnerà"], "«O Maryam, Allah ti ha scelta e purificata.»"),
"prophets_292": ("Come invocò Ayyub il suo Signore nella prova?", ["«Il male mi ha colpito, e Tu sei il più misericordioso»", "«Rendimi ricco»", "«Punisci i miei nemici»", "«Fammi re»"], "«Il male mi ha colpito, ma Tu sei il più misericordioso dei misericordiosi.»"),
"prophets_293": ("Che cosa insegnò Allah ad Adam?", ["Tutti i nomi", "La scrittura", "La navigazione", "Il calcolo"], "«E insegnò ad Adam tutti i nomi.»"),
"prophets_294": ("Quale profeta regnò su un regno che nessuno dopo di lui avrebbe avuto?", ["Sulayman", "Dawud", "Yusuf", "Dhul-Qarnayn"], "«Donami un regno tale che nessuno dopo di me ne abbia uno simile.»"),
"prophets_295": ("Quale profeta fu salvato con la sua famiglia, tranne sua moglie?", ["Lut", "Nuh", "Hud", "Salih"], "«Parti con la tua famiglia durante la notte… tranne tua moglie.»"),
"prophets_296": ("Contro che cosa Ibrahim mise in guardia il suo popolo?", ["Contro l'adorazione degli idoli", "Contro il commercio", "Contro i viaggi", "Contro la scrittura"], "«Prendi degli idoli come divinità?»"),
"prophets_297": ("Quale parola indica un inviato di Allah agli uomini?", ["Un messaggero (rasul)", "Un califfo", "Un compagno", "Un sapiente"], "Un rasul è un inviato di Allah, incaricato di un messaggio per gli uomini."),
"prophets_298": ("Come che cosa Allah ha inviato il Profeta ﷺ, secondo la sura Al-Ahzab?", ["Testimone, annunciatore e ammonitore", "Re e giudice", "Mercante", "Poeta"], "«O Profeta, ti abbiamo inviato come testimone, annunciatore e ammonitore» (33:45)."),
"prophets_299": ("Per quale scopo è stato inviato Muhammad ﷺ, secondo il Corano?", ["Come misericordia per i mondi", "Per regnare", "Per costruire", "Per commerciare"], "«E non ti abbiamo inviato se non come misericordia per i mondi.»"),
"prophets_300": ("Quale profeta il Corano chiama «un servo molto riconoscente»?", ["Nuh", "Lut", "Idris", "Ilyas"], "«In verità era un servo riconoscente» (17:3), detto di Nuh."),
"prophets_301": ("Quale segno ricevette Zakariyya dopo l'annuncio di suo figlio?", ["Non parlare alla gente per tre giorni", "Vedere una stella", "Sentire il tuono", "Camminare sull'acqua"], "«Il tuo segno sarà che non parlerai alla gente per tre giorni» (3:41)."),
"prophets_302": ("In quale lingua fu inviato ogni messaggero?", ["Nella lingua del suo popolo", "Solo in arabo", "In ebraico", "In una lingua del cielo"], "«Non abbiamo inviato alcun messaggero se non nella lingua del suo popolo.»"),
"prophets_303": ("Quale sura racconta la storia di un solo profeta dall'inizio alla fine?", ["La sura Yusuf", "La sura Al-Baqara", "La sura An-Nas", "La sura Al-Fatiha"], "«Ti raccontiamo il più bello dei racconti»: la storia di Yusuf."),
"prophets_304": ("Come descrive il Corano Ibrahim nella sura Maryam?", ["Un uomo veritiero, un profeta", "Un re", "Uno scriba", "Un mercante"], "«Era un uomo veritiero, un profeta.»"),
"prophets_305": ("Quale regina venne a trovare il profeta Sulayman?", ["La regina di Saba'", "La regina d'Egitto", "La regina di Babilonia", "La regina dello Yemen del nord"], "Ella si sottomise, insieme a Sulayman, ad Allah, Signore dei mondi."),
"prophets_306": ("Quale profeta chiese di vedere come Allah ridà la vita?", ["Ibrahim", "Musa", "Nuh", "Yunus"], "«Signore, mostrami come ridai la vita ai morti.»"),
"prophets_307": ("Quale profeta viaggiò per imparare da un servo sapiente?", ["Musa", "Yusuf", "Dawud", "Sulayman"], "Musa camminò finché incontrò un servo di Allah al quale Egli aveva dato una scienza."),
"prophets_308": ("Che cosa insegna la sura Al-Ikhlas su Allah?", ["Che Egli è Uno, e nessuno è uguale a Lui", "Che ha dei soci", "Che assomiglia alla Sua creazione", "Che ha un figlio"], "«Di': Egli è Allah, Unico… e nessuno è uguale a Lui.»"),
"prophets_309": ("Come chiamavano i Meccani il Profeta ﷺ prima della rivelazione?", ["Al-Amin, il degno di fiducia", "Il viaggiatore", "Il poeta", "Il giudice"], "La sua rettitudine era così nota che lo chiamavano al-Amin."),
"prophets_310": ("Chi presenta il Corano come il miglior esempio da seguire?", ["Il Messaggero di Allah ﷺ", "I re", "I poeti", "I mercanti"], "«Avete nel Messaggero di Allah un eccellente modello.»"),
"sira_251": ("In quale città nacque il Profeta ﷺ?", ["La Mecca", "Medina", "Gerusalemme", "Ta'if"], "Il Profeta ﷺ nacque alla Mecca, nella tribù dei Quraysh."),
"sira_252": ("In quale città emigrò il Profeta ﷺ?", ["Medina", "Ta'if", "Il Cairo", "Damasco"], "La Hijra andò dalla Mecca a Medina, allora chiamata Yathrib."),
"sira_253": ("Come si chiama la partenza dalla Mecca verso Medina?", ["La Hijra", "Il pellegrinaggio", "La conquista", "Il patto"], "La Hijra (l'Egira) segna l'inizio del calendario musulmano."),
"sira_254": ("Chi è la prima moglie del Profeta ﷺ?", ["Khadija", "'Aisha", "Hafsa", "Sawda"], "Khadija bint Khuwaylid, la prima a credere in lui."),
"sira_255": ("In quale grotta si nascose il Profeta ﷺ durante la Hijra?", ["La grotta di Thawr", "La grotta di Hira", "La grotta di Uhud", "La grotta di Quba'"], "Vi si nascose tre giorni con Abu Bakr prima di proseguire verso Medina."),
"sira_256": ("Qual è la prima parola rivelata al Profeta ﷺ?", ["«Leggi»", "«Prega»", "«Alzati»", "«Ascolta»"], "«Leggi, nel nome del tuo Signore che ha creato.»"),
"sira_257": ("Quale angelo portò la rivelazione al Profeta ﷺ?", ["Jibril", "Mika'il", "Israfil", "Malik"], "Jibril è l'angelo incaricato di far discendere la rivelazione."),
"sira_258": ("In quale città si trova la tomba del Profeta ﷺ?", ["Medina", "La Mecca", "Gerusalemme", "Ta'if"], "La sua tomba è a Medina, accanto alla sua moschea."),
"sira_259": ("Da quale tribù proveniva il Profeta ﷺ?", ["Quraysh", "Aws", "Khazraj", "Thaqif"], "Il Profeta ﷺ era dei Quraysh, la tribù della Mecca."),
"sira_260": ("Come si chiamano i compagni del Profeta ﷺ?", ["I Sahaba", "I Tabi'un", "Solo gli Ansar", "I Qurra'"], "I Sahaba sono coloro che videro il Profeta ﷺ credendo in lui."),
"sira_261": ("Chi accompagnò il Profeta ﷺ durante la Hijra?", ["Abu Bakr", "'Umar", "'Uthman", "Bilal"], "Abu Bakr fu il suo compagno nella grotta durante la Hijra."),
"sira_262": ("Chi era il muezzin del Profeta ﷺ?", ["Bilal", "Anas", "Zayd", "Salman"], "Bilal ibn Rabah chiamava alla preghiera a Medina."),
"sira_263": ("Come si chiama la prima battaglia dell'Islam?", ["Badr", "Uhud", "Khaybar", "Hunayn"], "Badr è la prima grande battaglia, nel secondo anno dell'Egira."),
"sira_264": ("Come si chiamano coloro che emigrarono dalla Mecca a Medina?", ["I Muhajirun", "Gli Ansar", "I Tabi'un", "I compagni di Ta'if"], "I Muhajirun sono gli emigrati; gli Ansar sono coloro che li accolsero."),
"sira_265": ("Come si chiamano gli abitanti di Medina che accolsero gli emigrati?", ["Gli Ansar", "I Muhajirun", "I Quraysh", "I Tabi'un"], "Gli Ansar, «i soccorritori», sono gli Aws e i Khazraj di Medina."),
"sira_266": ("Qual è la prima cosa che il Profeta ﷺ costruì a Medina?", ["Una moschea", "Un mercato", "Un palazzo", "Un muro di cinta"], "Costruì la sua moschea appena arrivato a Medina."),
"sira_267": ("Quale figlia del Profeta ﷺ sposò 'Ali?", ["Fatima", "Ruqayya", "Zaynab", "Umm Kulthum"], "Fatima, figlia del Profeta ﷺ, sposò 'Ali ibn Abi Talib."),
"sira_268": ("Chi fu il primo califfo dopo il Profeta ﷺ?", ["Abu Bakr", "'Umar", "'Uthman", "'Ali"], "Abu Bakr as-Siddiq fu il primo califfo."),
"sira_269": ("Qual era il nome antico di Medina?", ["Yathrib", "Bakka", "Ta'if", "Khaybar"], "Yathrib prese il nome di Madinat an-Nabi, la città del Profeta ﷺ."),
"sira_270": ("Quanti anni aveva il Profeta ﷺ alla prima rivelazione?", ["Quarant'anni", "Vent'anni", "Sessant'anni", "Trent'anni"], "La rivelazione gli giunse quando aveva quarant'anni."),
"sira_271": ("In quale città si trova la Ka'ba?", ["La Mecca", "Medina", "Gerusalemme", "Damasco"], "La Ka'ba si trova al centro della Moschea Sacra, alla Mecca."),
"sira_272": ("In quale città si trova la Moschea al-Aqsa?", ["Gerusalemme", "La Mecca", "Medina", "Il Cairo"], "La Moschea al-Aqsa si trova a Gerusalemme (al-Quds)."),
"sira_273": ("Quale zio del Profeta ﷺ lo protesse alla Mecca?", ["Abu Talib", "Abu Lahab", "Al-'Abbas", "Abu Sufyan"], "Abu Talib, il padre di 'Ali, protesse suo nipote contro i Quraysh."),
"sira_274": ("Quale mestiere faceva Khadija, la prima moglie del Profeta ﷺ?", ["Commerciante", "Medico", "Poetessa", "Tessitrice"], "Khadija era una commerciante rispettata della Mecca."),
"sira_275": ("Come si chiama l'ultimo pellegrinaggio del Profeta ﷺ?", ["Il Pellegrinaggio dell'Addio", "Il primo pellegrinaggio", "Il pellegrinaggio della conquista", "Il piccolo pellegrinaggio"], "Il Pellegrinaggio dell'Addio avvenne nell'anno 10 dell'Egira."),
"sira_276": ("Come si chiama il racconto della vita del Profeta ﷺ?", ["La Sira", "La Sunna", "Il Tafsir", "Il Fiqh"], "La Sira è il racconto della sua vita; la Sunna è ciò che egli disse e fece."),
"sira_277": ("Come si chiama una parola riportata dal Profeta ﷺ?", ["Un hadith", "Una sura", "Un versetto", "Un'invocazione"], "Un hadith è una parola, un atto o un'approvazione del Profeta ﷺ."),
"sira_278": ("Quali sono le due raccolte di hadith considerate più rigorose?", ["Sahih al-Bukhari e Sahih Muslim", "Due raccolte di poesie", "Due libri di storia", "Due dizionari"], "Insieme vengono chiamate «i due Sahih»."),
"sira_279": ("Quale califfo fece copiare il Corano e lo inviò alle province?", ["'Uthman", "Abu Bakr", "'Umar", "'Ali"], "'Uthman fece preparare copie ufficiali e le inviò alle città principali."),
"sira_280": ("Quanti califfi formano «i califfi ben guidati»?", ["Quattro", "Due", "Sette", "Dodici"], "Abu Bakr, 'Umar, 'Uthman e 'Ali."),
"sira_281": ("Verso quale direzione pregano i musulmani?", ["Verso la Ka'ba, alla Mecca", "Verso Gerusalemme", "Verso est", "Verso Medina"], "La qibla è la direzione della Ka'ba."),
"sira_282": ("Come si chiama questa direzione della preghiera?", ["La qibla", "Il mihrab", "Il minbar", "Il minareto"], "La qibla è la direzione; il mihrab è la nicchia che la indica."),
"sira_283": ("Come si chiama il luogo in cui i musulmani pregano insieme?", ["La moschea", "La scuola", "Il mercato", "La biblioteca"], "Il masjid è il luogo della prostrazione, la moschea."),
"sira_284": ("Come si chiama la chiamata alla preghiera?", ["L'adhan", "Il takbir", "Il tasbih", "Il dhikr"], "L'adhan è la chiamata; chi la lancia è il muezzin."),
"sira_285": ("In quale giorno i musulmani si riuniscono per la grande preghiera?", ["Il venerdì", "Il sabato", "La domenica", "Il lunedì"], "La preghiera del venerdì (al-jumu'a) riunisce la comunità ogni settimana."),
"sira_286": ("Come si chiama la persona che guida la preghiera?", ["L'imam", "Il muezzin", "Il giudice", "Lo hafiz"], "L'imam è colui dietro al quale la comunità si dispone per pregare."),
"sira_287": ("Come si chiama chi ha imparato a memoria tutto il Corano?", ["Uno hafiz", "Un imam", "Un muezzin", "Un giudice"], "Lo hafiz è colui che custodisce nella memoria l'intero Corano."),
"sira_288": ("Quale compagno è conosciuto come il più grande narratore di hadith?", ["Abu Hurayra", "Bilal", "Salman", "Anas"], "Abu Hurayra trascorse gli ultimi anni del Profeta ﷺ al suo fianco."),
"sira_289": ("Quale califfo è soprannominato as-Siddiq, «il veritiero»?", ["Abu Bakr", "'Umar", "'Uthman", "'Ali"], "Abu Bakr as-Siddiq, il primo uomo libero a credere."),
"sira_290": ("Quale califfo è soprannominato al-Faruq?", ["'Umar ibn al-Khattab", "Abu Bakr", "'Uthman", "'Ali"], "'Umar, che distingueva il vero dal falso, ricevette questo titolo."),
"sira_291": ("Quale califfo fece raccogliere il Corano in un unico volume?", ["Abu Bakr", "Mu'awiya", "Khalid", "Bilal"], "Abu Bakr ordinò di riunire in un'unica raccolta ciò che era stato messo per iscritto."),
"sira_292": ("Quale nonno allevò il Profeta ﷺ da bambino?", ["'Abd al-Muttalib", "Abu Sufyan", "Al-Walid", "'Utba"], "Suo nonno 'Abd al-Muttalib si prese cura di lui dopo la sua nascita."),
"sira_293": ("Come ricorda il Corano l'infanzia del Profeta ﷺ?", ["Allah lo trovò orfano e gli diede rifugio", "Era un re", "Era ricco fin dall'infanzia", "Viveva da solo nel deserto"], "«Non ti ha forse trovato orfano e ti ha dato rifugio?» (93:6)."),
"sira_294": ("Quale battaglia seguì quella di Badr?", ["Uhud", "Il Fossato", "Hunayn", "Tabuk"], "L'anno seguente ebbe luogo la battaglia di Uhud, vicino a Medina."),
"sira_295": ("Che cosa scavarono i musulmani intorno a Medina per difenderla?", ["Un fossato (al-Khandaq)", "Un pozzo", "Un tunnel", "Un canale"], "Scavarono un fossato, da cui il nome della battaglia del Fossato."),
"sira_296": ("Di chi era figlia 'Aisha, moglie del Profeta ﷺ?", ["Di Abu Bakr", "Di 'Umar", "Di 'Uthman", "Di 'Ali"], "'Aisha era la figlia di Abu Bakr as-Siddiq."),
"sira_297": ("Come chiama il Corano le mogli del Profeta ﷺ?", ["Le madri dei credenti", "Le serve", "Le compagne di viaggio", "Le emigrate"], "«E le sue mogli sono le loro madri» (33:6)."),
"sira_298": ("Quale compagno era allo stesso tempo cugino e genero del Profeta ﷺ?", ["'Ali ibn Abi Talib", "Bilal", "Salman", "Zayd"], "'Ali, cugino del Profeta ﷺ, sposò sua figlia Fatima."),
"sira_299": ("Come si chiama la moschea del Profeta ﷺ a Medina?", ["Al-Masjid an-Nabawi", "Al-Masjid al-Haram", "Al-Aqsa", "Quba'"], "La Moschea del Profeta, an-Nabawi, si trova a Medina."),
"sira_300": ("Come si chiama la cavalcatura del viaggio notturno del Profeta ﷺ?", ["Al-Buraq", "Al-'Adba'", "Ash-Shaqra'", "Al-Qaswa'"], "La cavalcatura del viaggio notturno è chiamata al-Buraq."),
"faith_151": ("Quanti sono i pilastri dell'Islam?", ["Cinque", "Tre", "Sei", "Dieci"], "Cinque: la testimonianza di fede, la preghiera, la zakat, il digiuno e il pellegrinaggio."),
"faith_152": ("Qual è il primo pilastro dell'Islam?", ["La testimonianza di fede (la Shahada)", "Il digiuno", "Il pellegrinaggio", "La zakat"], "Si entra nell'Islam testimoniando che non c'è dio all'infuori di Allah e che Muhammad ﷺ è il Suo messaggero."),
"faith_153": ("Quante preghiere obbligatorie compie un musulmano ogni giorno?", ["Cinque", "Tre", "Sette", "Due"], "Cinque preghiere, distribuite dall'alba alla notte."),
"faith_154": ("In quale mese digiunano i musulmani?", ["Ramadan", "Rajab", "Sha'ban", "Shawwal"], "«Il mese di Ramadan, nel quale è stato fatto scendere il Corano» (2:185)."),
"faith_155": ("Come si chiama l'elemosina obbligatoria dell'Islam?", ["La zakat", "Il du'a", "Il dhikr", "Il tawaf"], "La zakat è la parte dei propri beni che si dona ogni anno."),
"faith_156": ("Come si chiama il grande pellegrinaggio alla Mecca?", ["Lo hajj", "Il sa'y", "Il dhikr", "Il suhur"], "Lo hajj è il pellegrinaggio compiuto una volta nella vita da chi ne ha la possibilità."),
"faith_157": ("Quanti sono i pilastri della fede (arkan al-iman)?", ["Sei", "Quattro", "Cinque", "Sette"], "Credere in Allah, nei Suoi angeli, nei Suoi libri, nei Suoi messaggeri, nell'Ultimo Giorno e nel destino."),
"faith_158": ("In quanti dèi crede un musulmano?", ["In uno solo", "In due", "In tre", "In molti"], "«Di': Egli è Allah, Unico» (112:1)."),
"faith_159": ("Come chiamano Dio i musulmani in arabo?", ["Allah", "Malak", "Rasul", "Nabi"], "Allah è il nome del Creatore in arabo."),
"faith_160": ("Come si chiama il libro sacro dei musulmani?", ["Il Corano", "La Tawrat", "L'Injil", "Lo Zabur"], "Il Corano è il libro rivelato al Profeta Muhammad ﷺ."),
"faith_161": ("Come si chiama la Casa di Allah costruita alla Mecca?", ["La Ka'ba", "La Rawda", "Il Maqam", "Lo Hijr"], "«La prima Casa stabilita per gli uomini è quella di Bakka» (3:96)."),
"faith_162": ("Che cosa dice un musulmano prima di cominciare a mangiare?", ["Bismillah", "Amin", "Subhan Allah", "Allahumma"], "Il Profeta ﷺ insegnò a un bambino: «Di' Bismillah e mangia con la mano destra.»"),
"faith_163": ("Come si salutano i musulmani?", ["As-salamu 'alaykum", "Al-hamdu lillah", "Bismillah", "Allahu akbar"], "«As-salamu 'alaykum» significa: la pace sia su di voi."),
"faith_164": ("Che cosa si risponde ad «as-salamu 'alaykum»?", ["Wa 'alaykum as-salam", "Bismillah", "Amin", "Subhan Allah"], "Si ricambia il saluto: «e su di voi la pace»."),
"faith_165": ("Come si chiama la festa che segue il mese di Ramadan?", ["Eid al-Fitr", "Eid al-Adha", "Laylat al-Qadr", "'Ashura"], "Eid al-Fitr, la festa della rottura del digiuno."),
"faith_166": ("Come si chiama la festa del sacrificio?", ["Eid al-Adha", "Eid al-Fitr", "Il Mawlid", "Laylat al-Qadr"], "Eid al-Adha cade durante i giorni del pellegrinaggio."),
"faith_167": ("Come si chiamano le creature di Allah che Gli obbediscono sempre e non disobbediscono mai?", ["Gli angeli", "I jinn", "I profeti", "I compagni"], "Gli angeli eseguono ciò che Allah ordina loro senza mai disobbedire."),
"faith_168": ("Come si chiama il Paradiso in arabo?", ["Al-Janna", "As-Salat", "Ad-Du'a", "Al-Adhan"], "Al-Janna, letteralmente «il giardino», è la dimora promessa ai credenti."),
"faith_169": ("Come si chiama la purificazione con l'acqua che si fa prima di pregare?", ["L'abluzione (wudu)", "Il tawaf", "Il dhikr", "Il sa'y"], "Il wudu è la purificazione che precede la preghiera."),
"faith_170": ("Come si chiama un'unità della preghiera?", ["Una rak'a", "Una sura", "Un adhan", "Un tawaf"], "Una rak'a comprende la posizione in piedi, l'inchino e le prostrazioni."),
"faith_171": ("Quale sura si recita in ogni unità della preghiera?", ["Al-Fatiha", "Al-Ikhlas", "An-Nas", "Al-Kawthar"], "Al-Fatiha, la sura di apertura, viene recitata in ogni rak'a."),
"faith_172": ("Come si chiama ciò che è permesso nell'Islam?", ["Halal", "Haram", "Sunna", "Fard"], "Halal indica ciò che è lecito."),
"faith_173": ("Come si chiama ciò che è proibito nell'Islam?", ["Haram", "Halal", "Mubah", "Nafila"], "Haram indica ciò che è illecito."),
"faith_174": ("Quale carne proibisce il Corano?", ["La carne di maiale", "La carne di agnello", "La carne di manzo", "La carne di pollo"], "«Vi ha proibito la carogna, il sangue e la carne di maiale» (2:173)."),
"faith_175": ("Quale bevanda il Corano ordina di evitare?", ["Il vino e ogni sostanza inebriante", "Il latte", "Il miele", "L'acqua piovana"], "«Il vino, il gioco d'azzardo… sono un'abominazione: evitateli» (5:90)."),
"faith_176": ("Che cosa dice chi starnutisce, come insegnò il Profeta ﷺ?", ["Al-hamdu lillah", "Bismillah", "Allahu akbar", "Amin"], "«Quando uno di voi starnutisce, dica: al-hamdu lillah.»"),
"faith_177": ("Come si dice «la preghiera» in arabo?", ["As-salat", "As-sawm", "Az-zakat", "Al-hajj"], "As-salat è la preghiera rituale del musulmano."),
"faith_178": ("Come si chiama il chiedere qualcosa ad Allah con le proprie parole?", ["Il du'a", "Il tawaf", "L'adhan", "Il sa'y"], "Il du'a è l'invocazione, la richiesta rivolta ad Allah."),
"faith_179": ("Che cosa significa «al-hamdu lillah»?", ["Lode ad Allah", "Allah è il più grande", "Nel nome di Allah", "Gloria ad Allah"], "È il secondo versetto di Al-Fatiha: «Lode ad Allah, Signore dei mondi» (1:2)."),
"faith_180": ("Che cosa significa la parola «islam»?", ["Sottomissione ad Allah", "Ricchezza", "Viaggio", "Sapere"], "Islam deriva da una radice che significa sottomettersi ed essere in pace."),
"faith_181": ("Che cosa significa la parola «musulmano»?", ["Colui che si sottomette ad Allah", "Colui che viaggia", "Colui che insegna", "Colui che costruisce"], "Il musulmano è colui che si sottomette ad Allah soltanto."),
"faith_182": ("Chi ha creato i cieli e la terra, secondo il Corano?", ["Allah", "Gli angeli", "I profeti", "Il sole"], "«Lode ad Allah, che ha creato i cieli e la terra» (6:1)."),
"faith_183": ("Quanti nomi di Allah menziona l'hadith?", ["Novantanove", "Dieci", "Cinquanta", "Mille"], "«Allah ha novantanove nomi, cento meno uno.»"),
"faith_184": ("Che cosa fanno gli angeli chiamati «nobili scribi»?", ["Scrivono le nostre azioni", "Portano la pioggia", "Custodiscono la Ka'ba", "Insegnano l'arabo"], "«Nobili scribi, che sanno ciò che fate» (82:11-12)."),
"faith_185": ("Quale notte il Corano descrive come migliore di mille mesi?", ["Laylat al-Qadr", "La notte del venerdì", "La notte dell'Eid", "La prima notte di Ramadan"], "«La Notte del Destino è migliore di mille mesi» (97:3)."),
"faith_186": ("Come si chiama il credere in un Dio unico?", ["Il tawhid", "Il tawaf", "Il tayammum", "Il tarawih"], "Il tawhid è l'unicità di Allah, il cuore del messaggio di tutti i profeti."),
"faith_187": ("Come si chiama l'associare qualcuno ad Allah nell'adorazione?", ["Lo shirk", "Il dhikr", "Il du'a", "Il sabr"], "Lo shirk è l'associazione: adorare qualcos'altro insieme ad Allah."),
"faith_188": ("Come si chiama il giorno in cui tutti gli uomini saranno giudicati?", ["Il Giorno della Resurrezione", "Il giorno dell'Eid", "Il venerdì", "Il primo giorno di Ramadan"], "Yawm al-Qiyama, il Giorno della Resurrezione, in cui ognuno vedrà le proprie azioni."),
"faith_189": ("Quanti mesi ha l'anno secondo il Corano?", ["Dodici", "Dieci", "Quattordici", "Sei"], "«Il numero dei mesi presso Allah è dodici» (9:36)."),
"faith_190": ("Quante prostrazioni si fanno in una sola rak'a?", ["Due", "Una", "Tre", "Quattro"], "Ogni rak'a comprende due prostrazioni."),
"quran_151": ("Quante sure contiene il Corano?", ["Centoquattordici", "Sessanta", "Duecento", "Trenta"], "Il Corano contiene 114 sure, da Al-Fatiha ad An-Nas."),
"quran_152": ("Qual è la prima sura del Corano?", ["Al-Fatiha", "Al-Baqara", "An-Nas", "Ya-Sin"], "Al-Fatiha, «l'Aprente», è la prima sura."),
"quran_153": ("Che cosa significa la parola «Corano»?", ["La recitazione, la lettura", "Il cammino", "La luce", "Il giardino"], "Qur'an deriva da una radice che significa leggere e recitare."),
"quran_154": ("In quanti anni circa è stato fatto scendere il Corano?", ["Circa ventitré anni", "Una sola notte", "Cento anni", "Tre anni"], "La rivelazione è discesa nell'arco di circa ventitré anni."),
"quran_155": ("Come si chiama un versetto del Corano?", ["Un'aya", "Una sura", "Un juz'", "Un hadith"], "Ogni frase numerata del Corano è un'aya, un «segno»."),
"quran_156": ("Come si chiama un capitolo del Corano?", ["Una sura", "Un'aya", "Un juz'", "Una khutba"], "Il Corano è diviso in sure, ognuna con il proprio nome."),
"quran_157": ("Qual è la sura più lunga del Corano?", ["Al-Baqara", "Al-Fatiha", "Al-Kawthar", "An-Nas"], "Al-Baqara è la sura più lunga del Corano."),
"quran_158": ("Qual è la sura più breve del Corano?", ["Al-Kawthar", "Al-Baqara", "Al 'Imran", "An-Nisa'"], "Al-Kawthar ha soltanto tre versetti."),
"quran_159": ("Con quale frase iniziano quasi tutte le sure?", ["Nel nome di Allah, il Compassionevole, il Misericordioso", "Lode ad Allah", "Allah è il più grande", "Non c'è dio all'infuori di Allah"], "La basmala apre 113 delle 114 sure."),
"quran_160": ("Di chi è la parola il Corano?", ["Di Allah", "Del Profeta ﷺ", "Dell'angelo Jibril", "Dei compagni"], "Il Corano chiama se stesso «la parola di Allah» (kalam Allah) in 9:6."),
"quran_161": ("In quante parti (juz') è diviso il Corano?", ["Trenta", "Dieci", "Cinquanta", "Cento"], "Il Corano è diviso in trenta juz', uno per ogni notte di Ramadan."),
"quran_162": ("Quale sura porta il nome di una donna?", ["Maryam", "Yusuf", "Nuh", "Muhammad"], "La sura 19 porta il nome di Maryam."),
"quran_163": ("Come si chiamano le ultime due sure, con cui si chiede protezione?", ["Al-Mu'awwidhatan", "Al-Mathani", "Al-Mufassal", "Al-Hawamim"], "Al-Falaq e An-Nas sono chiamate al-Mu'awwidhatan, «le due protettrici»."),
"quran_164": ("Con quale parola inizia la sura Al-Fatiha, dopo la basmala?", ["Al-hamdu", "Qul", "Iqra'", "Inna"], "«Al-hamdu lillahi rabbi l-'alamin» apre Al-Fatiha."),
"quran_165": ("Come si chiama la spiegazione del significato del Corano?", ["Il tafsir", "Il tajwid", "Lo hifz", "Il tawaf"], "Il tafsir è la scienza che spiega il significato dei versetti."),
"quran_166": ("Quale sura non inizia con la basmala?", ["At-Tawba", "Al-Fatiha", "Al-Ikhlas", "An-Nasr"], "At-Tawba è l'unica sura che non si apre con la basmala."),
"quran_167": ("Come si chiama chi recita il Corano ad alta voce?", ["Un qari'", "Un muezzin", "Un imam", "Un khatib"], "Il qari' è il recitatore del Corano."),
"quran_168": ("In quale sura si trova il Versetto del Trono?", ["Al-Baqara", "Al-Kahf", "Ya-Sin", "Al-Mulk"], "Il Versetto del Trono è il versetto 255 della sura Al-Baqara."),
"quran_169": ("Che cosa significa «An-Nur», titolo della sura 24?", ["La luce", "La notte", "Il vento", "La montagna"], "An-Nur significa «la luce»."),
"quran_170": ("Quale sura porta il nome «Il Compassionevole»?", ["Ar-Rahman", "Al-Mulk", "Al-Fath", "As-Saff"], "La sura 55 si chiama Ar-Rahman."),
"quran_171": ("Quale sura porta il nome della caverna?", ["Al-Kahf", "Al-Fil", "An-Naml", "Al-Baqara"], "Al-Kahf significa «la caverna»."),
"quran_172": ("Che cosa significa «An-Nisa'», titolo della sura 4?", ["Le donne", "Gli uomini", "I bambini", "I viaggiatori"], "An-Nisa' significa «le donne»."),
"quran_173": ("Che cosa significa «Al-Ma'ida», titolo della sura 5?", ["La tavola imbandita", "La montagna", "Il ferro", "L'alba"], "Al-Ma'ida significa «la tavola imbandita»."),
"quran_174": ("Quale profeta dà il nome alla sura 71?", ["Nuh", "Hud", "Yunus", "Ibrahim"], "La sura 71 si chiama Nuh."),
"quran_175": ("Quanti versetti ha la sura Al-Fatiha?", ["Sette", "Tre", "Dieci", "Venti"], "Al-Fatiha ha sette versetti."),
"quran_176": ("Dove dice il Corano di essere conservato?", ["In una Tavola custodita", "In una grotta", "In un forziere", "Su una montagna"], "«È un Corano glorioso, su una Tavola custodita» (85:21-22)."),
"quran_177": ("Quale sura porta il nome della luna?", ["Al-Qamar", "Ash-Shams", "An-Najm", "Al-Layl"], "Al-Qamar significa «la luna»."),
"quran_178": ("Quale sura porta il nome del Giorno della Resurrezione?", ["Al-Qiyama", "Al-Fath", "Al-Hashr", "As-Saff"], "La sura 75 si chiama Al-Qiyama."),
"quran_179": ("Quale profeta dà il nome alla sura 14?", ["Ibrahim", "Muhammad ﷺ", "Yusuf", "Hud"], "La sura 14 si chiama Ibrahim."),
"quran_180": ("Che cosa significa «Al-Hadid», titolo della sura 57?", ["Il ferro", "L'oro", "Il legno", "La pietra"], "Al-Hadid significa «il ferro»."),
"virtues_101": ("Come ci dice il Corano di parlare ai nostri genitori?", ["Con parole rispettose, senza dire nemmeno «uff»", "Più forte di loro", "Restando sempre in silenzio", "Solo il venerdì"], "«Non dire loro “uff” e rivolgi loro parole rispettose» (17:23)."),
"virtues_102": ("Come si chiama un dono fatto liberamente, per bontà?", ["Una sadaqa", "Una zakat", "Un tawaf", "Un adhan"], "La sadaqa è l'elemosina volontaria, piccola o grande."),
"virtues_103": ("Che cosa consiglia il Profeta ﷺ, riguardo alla parola, a chi crede in Allah e nell'Ultimo Giorno?", ["Che dica il bene o taccia", "Che parli molto", "Che non parli mai", "Che parli solo con la sua famiglia"], "«Chi crede in Allah e nell'Ultimo Giorno dica il bene o taccia.»"),
"virtues_104": ("Come ci ha detto il Profeta ﷺ di comportarci con il nostro vicino?", ["Essere generosi con lui", "Evitarlo", "Non parlargli mai", "Chiedergli di andarsene"], "«Chi crede in Allah e nell'Ultimo Giorno sia generoso con il suo vicino.»"),
"virtues_105": ("Con chi è Allah, secondo il Corano?", ["Con i pazienti", "Con i più ricchi", "Con i più forti", "Con i più veloci"], "«In verità Allah è con i pazienti» (2:153)."),
"virtues_106": ("Che cosa proibisce il Corano di fare all'orfano?", ["Maltrattarlo", "Insegnargli a leggere", "Invitarlo a mangiare", "Giocare con lui"], "«Quanto all'orfano, non maltrattarlo» (93:9)."),
"virtues_107": ("Quale tipo di parola il Corano ci dice di evitare?", ["La parola menzognera", "La parola gentile", "Le parole di ringraziamento", "Le parole di saluto"], "«Ed evitate la parola menzognera» (22:30)."),
"virtues_108": ("Insieme al parente stretto, a chi il Corano ci dice di dare ciò che gli spetta?", ["Al povero e al viandante", "Al re e al giudice", "Al mercante", "Al poeta"], "«Da' al parente ciò che gli spetta, e così al povero e al viandante» (17:26)."),
"virtues_109": ("Che cosa promette Allah a chi Lo ringrazia?", ["Di dargli di più", "Di farlo viaggiare", "Di renderlo famoso", "Di farlo re"], "«Se sarete riconoscenti, certamente vi darò di più» (14:7)."),
"virtues_110": ("Come si dice «la pazienza» in arabo?", ["As-sabr", "Ash-shukr", "As-sidq", "Al-haya'"], "As-sabr è la costanza nella difficoltà e nell'obbedienza."),
"faith_191": ("Come si chiama il ricordare Allah, ripetendo le Sue lodi?", ["Il dhikr", "Lo hajj", "Il sa'y", "Il tayammum"], "Il dhikr è il ricordo di Allah con la lingua e con il cuore."),
"faith_192": ("Qual è il primo mese dell'anno islamico?", ["Muharram", "Ramadan", "Shawwal", "Rajab"], "L'anno dell'Egira si apre con il mese di Muharram."),
"faith_193": ("Come si chiama il tornare ad Allah dopo un peccato?", ["La tawba", "Il tawaf", "Il tajwid", "Il tarawih"], "La tawba è il pentimento: rimpiangere, smettere e tornare ad Allah."),
"faith_194": ("Chi provvede al sostentamento di ogni creatura sulla terra?", ["Allah", "I re", "I mercanti", "Gli angeli"], "«Non c'è creatura sulla terra il cui sostentamento non spetti ad Allah» (11:6)."),
"faith_195": ("In quale città si compie il pellegrinaggio?", ["Alla Mecca", "A Medina", "A Gerusalemme", "Al Cairo"], "Lo hajj si compie alla Mecca e nei suoi luoghi santi."),
"faith_196": ("Come si chiama chi compie il pellegrinaggio?", ["Un hajj (pellegrino)", "Un imam", "Un qari'", "Un muezzin"], "Il pellegrino è chiamato hajj."),
"faith_197": ("Che cosa conosce Allah, secondo il Corano, anche se lo si nasconde?", ["Ciò che c'è nei cuori", "Solo le azioni visibili", "Solo le parole dette", "Nulla di ciò che è nascosto"], "«Che nascondiate ciò che è nei vostri petti o lo mostriate, Allah lo sa» (3:29)."),
"faith_198": ("A chi è stato prescritto il digiuno, secondo il Corano?", ["Ai credenti, come a coloro che li hanno preceduti", "Solo ai viaggiatori", "Solo ai sapienti", "Solo ai bambini"], "«O voi che credete, vi è stato prescritto il digiuno come fu prescritto a coloro che vi hanno preceduto» (2:183)."),
"faith_199": ("Come si chiama la grande preghiera comunitaria del venerdì?", ["Salat al-jumu'a", "Salat al-'id", "Salat al-witr", "Salat ad-duha"], "Salat al-jumu'a riunisce i musulmani a mezzogiorno del venerdì."),
"faith_200": ("Come si dice «il digiuno» in arabo?", ["As-sawm", "As-salat", "Az-zakat", "Al-adhan"], "As-sawm è il digiuno, quarto pilastro dell'Islam."),
}
